<template><aside class="inspector"><div class="inspector-tabs"><button v-for="item in ['summary','reasoning','raw'] as const" :key="item" :class="{ active: tab === item }" @click="tab = item">{{ item }}</button></div><div class="inspector-content" v-if="tab === 'summary'"><div class="inspector-section"><small>CURRENT DIAGNOSIS</small><h3>{{ props.state.diagnosis || '조사 중' }}</h3><span class="confidence">{{ props.state.classification?.source === 'jev' ? `Jev ${Math.round((props.state.classification.confidence || 0) * 100)}%` : '규칙 기반 초기 판단' }}</span></div><div class="inspector-section"><small>EVIDENCE</small><p v-for="fact in props.state.confirmedFacts" :key="fact.id" class="evidence-line">✓ {{ fact.source }} · {{ fact.summary }}</p><p v-if="!props.state.confirmedFacts.length" class="soft-text">확인된 운영 도구 결과 없음</p></div><div class="inspector-section"><small>HYPOTHESES</small><p v-for="hypothesis in props.state.hypotheses" :key="hypothesis.id">{{ hypothesis.name }}</p><p v-if="!props.state.hypotheses.length" class="soft-text">추가 근거를 기다리는 중</p></div><div class="inspector-section"><small>NEXT ACTION</small><p>{{ props.state.recommendedAction }}</p></div></div><div class="inspector-content" v-else-if="tab === 'reasoning'"><div v-for="(step, index) in props.state.reasoningTrace" :key="index" class="trace-step"><small>{{ step.step }}</small><p>{{ step.text }}</p><span v-if="index < props.state.reasoningTrace.length - 1">↓</span></div><p v-if="!props.state.reasoningTrace.length" class="soft-text">판단 근거를 정리하는 중입니다.</p></div><div class="inspector-content" v-else><pre>{{ JSON.stringify(props.state, null, 2) }}</pre></div></aside></template>
